=135,["2003959"]=134,["2003960"]=133,["2003961"]=132,["2003962"]=131,["2003963"]=130,["2003964"]=168,["2003965"]=165,["2003966"]=167,["2003967"]=164,["2003968"]=166,["2003969"]=163,["2003970"]=167,["2003971"]=164,["2003972"]=174,["2003973"]=173,["2003974"]=172,["2003975"]=171,["2003976"]=170,["2003977"]=169,["2003978"]=173,["2003979"]=172,["2003980"]=141,["2003981"]=146,["2003982"]=145,["2003983"]=144,["2003984"]=143,["2003985"]=142,["2003986"]=151,["2003987"]=150,["2003988"]=149,["2003989"]=148,["2003990"]=147,["2003991"]=152,["2003992"]=153,["2003993"]=154,["2003994"]=155,["2003995"]=156,["2003996"]=157,["2003997"]=158,["2003998"]=159,["2003999"]=160,["2004000"]=161,["2004001"]=162,["2004002"]=140,["2004003"]=139,["2004004"]=138,["2004005"]=137,["2004006"]=136,["2004007"]=135,["2004008"]=134,["2004009"]=133,["2004010"]=132,["2004011"]=131,["2004012"]=130,["2004013"]=168,["2004014"]=165,["2004015"]=167,["2004016"]=164,["2004017"]=166,["2004018"]=163,["2004019"]=167,["2004020"]=164,["2004021"]=174,["2004022"]=173,["2004023"]=172,["2004024"]=171,["2004025"]=170,["2004026"]=169,["2004027"]=173,["2004028"]=172},["boss"]={["npc"]=2000980,["condition"]=134,["grid"]=175,["rewardResetMs"]=7200000,["aldikar"]={["npc"]=2000981,["condition"]=135,["emote"]="unsheathes a knife and shaves the beard from Narandi's face and returns the head to you, 'The Dain will require the beard for his trophy room, please accept this ring on his behalf. May its effect aid you as you have aided us. Be certain to present the ring to the Dain when you're in town. If you remain an ally he will be most gracious, but be warned, if you fall from his good graces he will keep the ring.'"},["survivors"]={{["npc"]=2000982,["condition"]=136,["stage"]=2000990,["reward"]=1746,["emote"]="pries a crown from the head of Narandi, 'The halls of Thurgadin will echo with praises to you for as long as we grace the face of this land. May this crown serve you well. Honor through battle!'"},{["npc"]=2000983,["condition"]=137,["stage"]=2000991,["reward"]=1744,["emote"]="unhooks a glowing earring from Narandi's shorn head, 'Hmm, this looks like something special. Take it, $name, you've earned it! Be well.' "},{["npc"]=2000984,["condition"]=138,["stage"]=2000992,["reward"]=1743,["emote"]="gives a gentle, warm smile and slight nod of his head in warm welcoming, 'Good day to you, $name, and welcome to the district of Selia. We are children of the light -- beings who valiantly uphold the ways of honor, valor, and merits of goodly faith and virtue. Rather, we are crusaders of these things, collectively comprising the beacon of these traits within the universe in our position in New Tanaan. We are quite pleased to have you approach us with such confidence -- perhaps the inner light has brought you to us, seeking a way to unlock the purity of these merits that you faintly mirror now. If you are seeking council in the ways of enchantments, then I would be more than pleased and honored to aid you where I can, my friend.'"},{["npc"]=2000985,["condition"]=139,["stage"]=2000993,["reward"]=1742,["emote"]="removes a choker from the severed head and returns both items to you, 'Congratulations on your victory, $name. I couldn't have done a better job myself. May Brell protect and watch over you and your friends. Farewell.' "},{["npc"]=2000986,["condition"]=140,["stage"]=2000994,["reward"]=1745,["emote"]="picks up a stick and hits the back of the dismembered head with all his might, knocking one of its eyes out of the socket, 'Bastard killed my brother! Hope his ghost felt that one!'"}}},["defenders"]={["intervalMs"]=12000,["speech"]={"Good citizens of Thurgadin, hear me! Our city, our people, our very lives are in danger this day. The Kromrif are at this very moment marching towards us in an offensive they hope will bring about our demise...","I hereby command, by authority of Dain Frostreaver the Fourth, that all able bodied Coldain fight to the death in defense of our land. Children, disabled citzens, and unseasoned travelers are advised to evacuate immediately!","My fellow soldiers, take heart! For we are not alone in this endeavor. One among us, an outlander, has earned the title Hero of the Dain for valiant service to our people. This newcomer has brought with him allies that will fight alongside you to help bring about our victory.","My friends... Brell did not place us here so many centuries ago to be slaughtered by these heathens. Nor did our forefather, Colin Dain, sacrifice himself simply to have us fail here now. Through these events we were brought to this day to test our strength and our faith.","Will we be shackled together to slave away in Kromrif mines or will we stand united and feed these beasts Coldain blades? By Brell, I promise you, it is better to die on our feet than to live on our knees!","TROOPS, TAKE YOUR POSITIONS!"},["conditions"]={["commander"]=141,["leaders"]=142,["archers"]=143,["axemen"]=144,["east"]=145,["south"]=146,["soldiers"]=147},["stageCommanderCondition"]=148,["commander"]=2000995,["orders"]={{["phrase"]="garadain to my side",["helper"]="GaradainHelp",["npcTypes"]={2000993,2000998,2000999},["leader"]=2000993},{["phrase"]="dobbin assist me",["helper"]="DobbinHelp",["npcTypes"]={2000992,2001000},["leader"]=2000992},{["phrase"]="churn protect me",["helper"]="ChurnHelp",["npcTypes"]={2000990,2000997},["leader"]=2000990},{["phrase"]="corbin attack",["helper"]="CorbinHelp",["npcTypes"]={2000991,2001001,2001002},["leader"]=2000991}},["roles"]={{["npc"]=2000990,["spawn"]=2000990,["stage"]=2000960,["condition"]=142,["guard"]={1544,-1070,317.3697204589844,0}},{["npc"]=2000991,["spawn"]=2000991,["stage"]=2000961,["condition"]=142,["guard"]={100,-2880,-148.77659606933594,0}},{["npc"]=2000992,["spawn"]=2000992,["stage"]=2000962,["condition"]=142,["guard"]={0,-1090,19.94844627380371,128}},{["npc"]=2000993,["spawn"]=2000993,["stage"]=2000963,["condition"]=142,["guard"]={-1840,-570,66.49685668945312,128}},{["npc"]=2000994,["spawn"]=2000994,["stage"]=2000964,["condition"]=142,["guard"]={870,-1095,51.873748779296875,52}},{["npc"]=2000995,["spawn"]=2000995,["stage"]=2000965,["condition"]=141,["guard"]={-112,30,96.800048828125,128}}}}}
local war={}
local function active(e) return e.qglobals.coldainWarPhase=="preparing" or e.qglobals.coldainWarPhase=="war" or e.qglobals.coldainWarPhase=="boss" end
local function clear_pools()
 for _,wave in ipairs(data.waves) do
  for _,group in ipairs(wave.groups) do eq.spawn_condition("greatdivide",0,group.condition,0) end
 end
 eq.spawn_condition("greatdivide",0,data.spearmanCondition,0)
end
local function clear_outcomes()
 eq.spawn_condition("greatdivide",0,data.boss.condition,0)
 eq.spawn_condition("greatdivide",0,data.boss.aldikar.condition,0)
 for _,role in ipairs(data.boss.survivors) do eq.spawn_condition("greatdivide",0,role.condition,0) end
end
local function clear_defenders()
 for _,id in pairs(data.defenders.conditions) do eq.spawn_condition("greatdivide",0,id,0) end
end
function war.fail(e)
 if not active(e) and e.qglobals.coldainWarPhase~="lost" then return end
 eq.stop_all_timers()
 eq.set_global("coldainWarPhase","failed",3,"F")
 eq.del_global("coldainWarPending")
 clear_pools()
 clear_outcomes()
 clear_defenders()
 for _,id in ipairs(data.stageConditions) do eq.spawn_condition("greatdivide",0,id,0) end
 eq.set_timer("war_reset",data.failureResetMs)
 e.self:Shout("The defense of Thurgadin has failed.")
end
function war.begin(e)
 if e.qglobals.coldainWarPhase~="preparing" or e.qglobals.coldainWarStarted then return end
 eq.stop_timer("staging_deadline")
 eq.set_global("coldainWarStarted","1",3,"F")
 eq.set_global("coldainWarWave","0",3,"F")
 eq.spawn_condition("greatdivide",0,data.defenders.conditions.commander,1)
 eq.spawn_condition("greatdivide",0,data.defenders.stageCommanderCondition,0)
 eq.set_global("coldainWarDeployment","0",3,"F")
 eq.set_timer("war_deploy",data.defenders.intervalMs)
 eq.set_timer("war_wave",data.preparationMs)
end
function war.timer(e)
 if e.timer=="war_reset" then
  eq.stop_all_timers()
  clear_pools();clear_outcomes();clear_defenders()
  for _,key in ipairs({"coldainWarPhase","coldainWarStarted","coldainWarWave","coldainWarPending","coldainWarController","coldainWarStaging","coldainWarSurvivorsSaved","coldainWarDeployment"}) do eq.del_global(key) end
  for _,role in ipairs(data.boss.survivors) do eq.del_global("coldainWarSurvivor"..role.stage) end
  eq.spawn_condition("greatdivide",0,data.towerCondition,1)
  return true
 elseif e.timer=="war_guard" then
  if e.qglobals.coldainWarPhase=="lost" then war.fail(e)
  elseif e.qglobals.coldainWarPhase=="won" then
   eq.stop_timer(e.timer)
   eq.set_timer("war_reset",data.boss.rewardResetMs)
  elseif not active(e) then eq.stop_timer(e.timer)
  elseif not e.qglobals.coldainWarSurvivorsSaved then
   if not eq.get_entity_list():IsMobSpawnedByNpcTypeID(data.defenders.commander) then war.fail(e) end
  end
  return true
 elseif e.timer=="war_deploy" then
  if e.qglobals.coldainWarPhase=="lost" then war.fail(e);return true end
  if not active(e) then eq.stop_timer(e.timer);return true end
  local step=tonumber(e.qglobals.coldainWarDeployment or "0")+1
  assert(step>=1 and step<=7,"invalid defender deployment cursor")
  if step<=6 then
   local commander=eq.get_entity_list():GetNPCByNPCTypeID(data.defenders.commander)
   assert(commander.valid,"battle commander has not been published")
   commander:Shout(data.defenders.speech[step])
   if step==1 then eq.set_timer("war_guard",data.publicationTickMs) end
  end
  local groups={"archers","axemen","east","south","soldiers"}
  if step<=5 then eq.spawn_condition("greatdivide",0,data.defenders.conditions[groups[step]],1)
  elseif step==6 then
   eq.spawn_condition("greatdivide",0,data.defenders.conditions.leaders,1)
   eq.spawn_condition("greatdivide",0,23,0)
   eq.set_timer("war_defender_launch",data.publicationTickMs)
  else
   eq.spawn_condition("greatdivide",0,data.spearmanCondition,1)
   eq.stop_timer(e.timer)
  end
  eq.set_global("coldainWarDeployment",tostring(step),3,"F")
  return true
 elseif e.timer=="war_defender_launch" then
  if not active(e) then eq.stop_timer(e.timer);return true end
  -- Check the whole formation before posting any signals. A publication race
  -- retries this same timer; it must not partially launch and duplicate orders.
  local actors={}
  for _,r in ipairs(data.defenders.roles) do
   local npc=eq.get_entity_list():GetNPCBySpawnID(r.spawn)
   assert(npc.valid,"defender commander has not been published")
   table.insert(actors,npc)
  end
  for _,npc in ipairs(actors) do npc:Signal(1) end
  eq.stop_timer(e.timer)
  return true
 elseif e.timer=="war_wave" then
  eq.stop_timer(e.timer)
  if not active(e) then return true end
  local number=tonumber(e.qglobals.coldainWarWave or "0")+1
  if number>#data.waves then
   eq.set_global("coldainWarPhase","boss",3,"F")
   eq.spawn_condition("greatdivide",0,data.boss.condition,1)
   for name,id in pairs(data.defenders.conditions) do
    if name~="leaders" and name~="commander" then eq.spawn_condition("greatdivide",0,id,0) end
   end
   eq.set_timer("war_boss_launch",data.publicationTickMs)
   return true
  end
  local group=number==1 and data.firstGroup or eq.ChooseRandom(1,2,3,4,5)
  eq.set_global("coldainWarPhase","war",3,"F")
  eq.set_global("coldainWarWave",tostring(number),3,"F")
  eq.set_global("coldainWarPending",tostring(number)..":"..tostring(group),3,"F")
  eq.spawn_condition("greatdivide",0,data.waves[number].groups[group].condition,1)
  eq.set_timer("war_launch",data.publicationTickMs)
  eq.set_timer("war_wave",data.waves[number].intervalMs)
  return true
 elseif e.timer=="war_boss_launch" then
  if e.qglobals.coldainWarPhase~="boss" then eq.stop_timer(e.timer);return true end
  local npc=eq.get_entity_list():GetNPCBySpawnID(data.boss.npc)
  assert(npc.valid,"Narandi has not been published")
  npc:Signal(1);eq.stop_timer(e.timer)
  return true
 elseif e.timer=="war_launch" then
  if not active(e) then eq.stop_timer(e.timer);return true end
  local number,group=(e.qglobals.coldainWarPending or ""):match("^(%d+):(%d+)$")
  number,group=tonumber(number),tonumber(group)
  assert(number and data.waves[number] and group and data.waves[number].groups[group],"invalid pending war launch")
  local sent=0
  for _,id in ipairs(data.waves[number].groups[group].spawns) do
   local npc=eq.get_entity_list():GetNPCBySpawnID(id)
   if npc.valid then npc:Signal(1);sent=sent+1 end
  end
  -- Wait for ordinary condition publication; a member already killed before
  -- dispatch is skipped. Cadence remains independent of this launch retry.
  assert(sent>0,"war formation has not been published")
  eq.stop_timer(e.timer)
  eq.del_global("coldainWarPending")
  return true
 end
 return false
end
function war.defender_start(e)
 if not active(e) then return false end
 local role=nil
 for _,r in ipairs(data.defenders.roles) do if r.npc==e.self:GetNPCTypeID() then role=r end end
 assert(role,"defender has no reviewed guard position")
 e.self:SetRunning(true)
 e.self:MoveTo(role.guard[1],role.guard[2],role.guard[3],role.guard[4],true)
 return true
end
function war.defender_death(e)
 if active(e) and e.self:GetNPCTypeID()==data.defenders.commander then
  -- Death cannot create a reliable timer on its retired source lifetime.
  -- The live controller's deployment/guard clock settles the loss and reset.
  eq.set_global("coldainWarPhase","lost",3,"F")
 end
end
function war.scout_order(e)
 if e.qglobals.coldainWarPhase~="preparing" and e.qglobals.coldainWarPhase~="war" then return end
 local message=e.message:lower():gsub("[%p]","")
 if message:find("hail",1,true) then
  e.self:Say("Your orders: [Garadain to my side], [Dobbin assist me], [Churn protect me], [Corbin attack], or [For the Dain, attack].")
  return
 end
 local chosen={}
 for _,order in ipairs(data.defenders.orders) do
  if message:find(order.phrase,1,true) or message:find("for the dain attack",1,true) then
   if eq.get_entity_list():IsMobSpawnedByNpcTypeID(order.leader) then for _,id in ipairs(order.npcTypes) do chosen[id]=true end end
  end
 end
 for npc in eq.get_entity_list():GetNPCList().entries do
  if npc.valid and chosen[npc:GetNPCTypeID()] then
   npc:MoveTo(e.self:GetX(),e.self:GetY(),e.self:GetZ(),0,false)
  end
 end
end
function war.start_boss(e)
 if e.qglobals.coldainWarPhase~="boss" then return false end
 eq.start(data.boss.grid)
 return true
end
function war.boss_waypoint(e)
 if e.qglobals.coldainWarPhase~="boss" then return end
 if e.wp==3 then e.self:Shout("Meddling fools, you are no match for the likes of me. Be warned... Engage me at your own peril!")
 elseif e.wp==8 then eq.signal(data.controller,3) end
end
function war.boss_combat(e)
 if not e.joined or e.qglobals.coldainWarPhase~="boss" or e.qglobals.coldainWarSurvivorsSaved then return end
 for _,role in ipairs(data.boss.survivors) do
  local living=eq.get_entity_list():IsMobSpawnedByNpcTypeID(role.stage)
  eq.set_global("coldainWarSurvivor"..role.stage,living and "1" or "0",3,"F")
 end
 eq.set_global("coldainWarSurvivorsSaved","1",3,"F")
 for _,id in ipairs(data.stageConditions) do eq.spawn_condition("greatdivide",0,id,0) end
 eq.spawn_condition("greatdivide",0,data.defenders.conditions.leaders,0)
end
function war.boss_death(e)
 if e.qglobals.coldainWarPhase~="boss" then return end
 -- Actual server death dispatch occurs after the source lifetime is dead.
 -- Write shared conditions directly; a signal from that dead source is stale.
 clear_pools();clear_outcomes();clear_defenders()
 if tonumber(e.killer_npc_id or 0)>0 then
  eq.set_global("coldainWarPhase","lost",3,"F")
  return
 end
 assert(e.qglobals.coldainWarSurvivorsSaved=="1","Narandi death has no survivor snapshot")
 eq.set_global("coldainWarPhase","won",3,"F")
 eq.spawn_condition("greatdivide",0,data.boss.aldikar.condition,1)
 for _,role in ipairs(data.boss.survivors) do
  if e.qglobals["coldainWarSurvivor"..role.stage]=="1" then eq.spawn_condition("greatdivide",0,role.condition,1) end
 end
end
function war.reward_trade(e)
 local item_lib=require("items")
 local role=nil
 if e.self:GetNPCTypeID()==data.boss.aldikar.npc then role=data.boss.aldikar
 else for _,candidate in ipairs(data.boss.survivors) do if e.self:GetNPCTypeID()==candidate.npc then role=candidate end end end
 if role and e.qglobals.coldainWarPhase=="won" and eq.get_spawn_condition("greatdivide",0,role.condition)==1 then
  local required=role.reward and {item1=1741} or {item1=1739,item2=30369}
  if item_lib.check_turn_in(e.trade,required) then
   e.self:Emote(role.emote:gsub("%$name",function() return e.other:GetCleanName() end))
   e.other:SummonItem(1741);e.other:SummonItem(role.reward or 30385)
   e.other:Faction(406,100,0);e.other:Faction(405,25,0)
   e.other:Faction(448,-10,0);e.other:Faction(419,-50,0)
   e.other:AddEXP(5000)
   -- Disabling this public role prevents every observer from making another
   -- fresh claim; owner-only eq.depop would leave a second public opportunity.
   eq.spawn_condition("greatdivide",0,role.condition,0)
  end
 end
 item_lib.return_items(e.self,e.other,e.trade)
end
function war.start_actor(e)
 if e.qglobals.coldainWarPhase~="war" then return false end
 local route=data.routes[tostring(e.self:GetID())]
 assert(route,"war actor has no reviewed route")
 eq.start(route)
 return true
end
function war.actor_waypoint(e)
 -- A surviving giant from the last wave can still breach during Narandi.
 -- Boss publication is not victory and must not turn off that loss condition.
 if e.qglobals.coldainWarPhase~="war" and e.qglobals.coldainWarPhase~="boss" then return end
 if e.wp==3 then e.self:SetRunning(true)
 elseif e.wp==8 then eq.signal(data.controller,3) end
end
return war
